import { Flags } from '@oclif/core';
import { organizationIdFlagConfig, projectIdFlagConfig, ResolvedCommand } from '../../baseCommands.js';
import { functionListCore } from '../../cores/functions/list.js';
import { Logger } from '../../utils/logger.js';
export default class FunctionsListCommand extends ResolvedCommand {
    static needs = ['scope'];
    static hidden = true;
    static summary = 'List deployed Sanity Functions';
    static description = `Lists functions deployed directly in the selected project or organization scope. The local Blueprint config supplies the scope by default.

Use --project-id or --organization-id to select a scope without a local Blueprint. Organization results include organization-scoped functions only.`;
    static examples = [
        '<%= config.bin %> <%= command.id %>',
        '<%= config.bin %> <%= command.id %> --verbose',
        '<%= config.bin %> <%= command.id %> --project-id <projectId>',
        '<%= config.bin %> <%= command.id %> --organization-id <organizationId>',
        '<%= config.bin %> <%= command.id %> --project-id <projectId> --json',
    ];
    static flags = {
        'project-id': Flags.string({ ...projectIdFlagConfig }),
        'organization-id': Flags.string({ ...organizationIdFlagConfig }),
        verbose: Flags.boolean({
            char: 'v',
            description: 'Show function configuration details',
            default: false,
        }),
    };
    async run() {
        const result = await functionListCore({
            log: Logger(this.log.bind(this), this.flags),
            auth: this.auth,
            flags: this.flags,
        });
        if (!result.success)
            this.coreError(result);
        return result.json;
    }
}
